procedure SortByChoice(a: array of real);
begin
  for var i:=0 to a.Length-2 do
  begin
    var min := a[i]; 
    var ind := i;
    for var j:=i+1 to a.Length-1 do
      if a[j]<min then
      begin
        min := a[j];
        ind := j;
      end;
    a[ind] :=a [i];
    a[i] := min;
  end;
end;

